for update

mapper.update:
update batch_rabbits br
inner join rabbits r on r.id = br.rabbit_id
inner join (
    select selected_ids.id
    from (
        select scoped_br.id
        from batch_rabbits scoped_br
        inner join batches scoped_b on scoped_b.id = scoped_br.batch_id
        where scoped_b.house_id = #{houseId}
          and scoped_br.batch_id = #{batchId}
          and scoped_br.is_active = true
        order by scoped_br.id
        limit #{limit}
    ) selected_ids
) selected on selected.id = br.id
set br.is_active = false,
    br.exit_date = #{exitDate},
    br.remark = #{remark},
    br.update_by = #{updateBy},
    br.update_time = now(),
    r.state_version = r.state_version + 1,
    r.update_by = #{updateBy},
    r.update_time = now()
where r.house_id = #{houseId}
  and br.batch_id = #{batchId}
  and br.is_active = true

update batch_rabbits
set is_event_notified = true,
    event_notify_date = now(),
    update_by = #{updateBy},
    update_time = now()
where id in (
    select id
    from (
        select br.id
        from batch_rabbits br
        inner join batches b on b.id = br.batch_id
        where b.house_id = #{houseId}
          and br.is_active = true
          and br.next_event_date is not null
          and br.next_event_date <= #{today}
          and br.is_event_notified = false

        order by br.id
        limit #{limit}
    ) due_batch_events
)

mapper.select:
select br.id, br.batch_id, br.rabbit_id, br.male_rabbit_id, br.latest_cycle_id, br.current_nursing_kits, br.nursing_litter_count, br.join_reason, br.batch_role, br.current_status, br.last_event_date, br.next_event_date, br.next_event_type, br.is_active, br.join_date, br.exit_date, r.type as rabbit_type, r.gender as rabbit_gender, r.cage_id,
r.current_stage, r.current_cycle_id from batch_rabbits br inner join rabbits r on r.id = br.rabbit_id where br.batch_id = #{batchId}
and br.batch_role = #{role}
and br.is_active = #{active}
order by br.id asc

select br.id, br.batch_id, br.rabbit_id, br.male_rabbit_id, br.latest_cycle_id,
       br.current_nursing_kits, br.nursing_litter_count, br.join_reason, br.batch_role, br.current_status,
       br.last_event_date, br.next_event_date, br.next_event_type, br.is_active, br.join_date, br.exit_date,
       r.type as rabbit_type, r.gender as rabbit_gender, r.cage_id,
       r.current_stage, r.current_cycle_id
from batch_rabbits br
inner join batches b on b.id = br.batch_id
inner join rabbits r on r.id = br.rabbit_id
where b.house_id = #{houseId}
  and r.house_id = #{houseId}
  and br.rabbit_id = #{rabbitId}

    and br.is_active = #{active}

order by br.id asc
